class ConfError extends Error {}
const fail = (m) => { throw new ConfError(m) }

const isWs = (c) => c === ' ' || c === '\t'
const isBare = (c) => c !== undefined && /[A-Za-z0-9_-]/.test(c)

const table = () => ({ t: 'table', m: new Map(), hdr: false })
const scalar = (t, v) => ({ t, v })

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  skip() { while (isWs(this.s[this.i])) this.i++ }
  // next significant char; comment characters count as end of line
  peek() {
    this.skip()
    const c = this.s[this.i]
    return c === '#' || c === ';' ? undefined : c
  }
}

function parseString(L, q) {
  const s = L.s
  L.i++
  let out = ''
  if (q === "'") {
    const e = s.indexOf("'", L.i)
    if (e < 0) fail('unterminated string')
    out = s.slice(L.i, e)
    L.i = e + 1
    return out
  }
  for (;;) {
    const c = s[L.i]
    if (c === undefined) fail('unterminated string')
    if (c === '"') { L.i++; return out }
    if (c === '\\') {
      const n = s[L.i + 1]
      if (n === undefined) fail('unterminated string')
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, n)) { out += map[n]; L.i += 2; continue }
      if (n === 'u') {
        const h = s.slice(L.i + 2, L.i + 6)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        L.i += 6
        continue
      }
      fail('invalid escape \\' + String.fromCodePoint(s.codePointAt(L.i + 1)))
    }
    out += c
    L.i++
  }
}

function parseName(L) {
  const c = L.s[L.i]
  if (c === '"' || c === "'") return parseString(L, c)
  const st = L.i
  while (isBare(L.s[L.i])) L.i++
  if (L.i === st) fail('expected a name')
  return L.s.slice(st, L.i)
}

function parseDotted(L) {
  L.skip()
  const parts = [parseName(L)]
  for (;;) {
    L.skip()
    if (L.s[L.i] !== '.') return parts
    L.i++
    L.skip()
    parts.push(parseName(L))
  }
}

const INT = /^[+-]?\d+(_\d+)*$/
const FLOAT = /^[+-]?\d+(_\d+)*(\.\d+(_\d+)*)?([eE][+-]?\d+(_\d+)*)?$/

function parseValue(L, base) {
  const c = L.peek()
  if (c === undefined || c === ',' || c === ']' || c === '}') fail('expected a value')
  if (c === '"' || c === "'") return scalar('string', parseString(L, c))
  if (c === '[') return parseArray(L, base)
  if (c === '{') return parseInline(L, base)
  const st = L.i
  while (L.i < L.s.length && !isWs(L.s[L.i]) && !',]};'.includes(L.s[L.i])) L.i++
  const w = L.s.slice(st, L.i)
  if (w === 'true') return scalar('boolean', true)
  if (w === 'false') return scalar('boolean', false)
  if (INT.test(w)) return scalar('integer', BigInt(w.replace(/_/g, '')))
  if (FLOAT.test(w)) return scalar('float', Number(w.replace(/_/g, '')))
  fail('invalid value ' + w)
}

function parseArray(L, base) {
  L.i++
  const node = { t: 'array', items: [], aot: false }
  if (L.peek() === ']') { L.i++; return node }
  for (;;) {
    if (L.peek() === undefined) fail('unterminated array')
    node.items.push(parseValue(L, base))
    const c = L.peek()
    if (c === ']') { L.i++; return node }
    if (c !== ',') fail('unterminated array')
    L.i++
    if (L.peek() === ']') { L.i++; return node }
  }
}

function parseInline(L, base) {
  L.i++
  const node = table()
  if (L.peek() === '}') { L.i++; return node }
  for (;;) {
    if (L.peek() === undefined) fail('unterminated inline table')
    const keys = parseDotted(L)
    if (L.peek() !== '=') {
      if (L.peek() === undefined) fail('expected = in an inline table')
      fail('expected = in an inline table')
    }
    L.i++
    const v = parseValue(L, base.concat(keys))
    assign(node, base, keys, v)
    const c = L.peek()
    if (c === '}') { L.i++; return node }
    if (c !== ',') fail('unterminated inline table')
    L.i++
  }
}

function walk(cur, base, keys) {
  const path = base.slice()
  for (const k of keys) {
    path.push(k)
    let n = cur.m.get(k)
    if (n === undefined) { n = table(); cur.m.set(k, n) }
    else if (n.t === 'array' && n.aot) n = n.items[n.items.length - 1]
    else if (n.t !== 'table') fail(path.join('.') + ' is not a table')
    cur = n
  }
  return cur
}

function assign(cur, base, keys, v) {
  const parent = walk(cur, base, keys.slice(0, -1))
  const last = keys[keys.length - 1]
  if (parent.m.has(last)) fail('key ' + base.concat(keys).join('.') + ' is defined twice')
  parent.m.set(last, v)
}

function parseHeader(L, root) {
  const aot = L.s[L.i + 1] === '['
  L.i += aot ? 2 : 1
  const keys = parseDotted(L)
  L.skip()
  const closeCh = L.s[L.i]
  if (closeCh !== ']') fail('unterminated table header')
  L.i++
  if (aot) {
    if (L.s[L.i] !== ']') fail('unterminated table header')
    L.i++
  }
  if (L.peek() !== undefined) fail('trailing text after a table header')
  const parent = walk(root, [], keys.slice(0, -1))
  const last = keys[keys.length - 1]
  const path = keys.join('.')
  const n = parent.m.get(last)
  if (aot) {
    if (n === undefined) {
      const a = { t: 'array', items: [], aot: true }
      parent.m.set(last, a)
      const t = table(); t.hdr = true
      a.items.push(t)
      return { cur: t, path: keys }
    }
    if (n.t !== 'array' || !n.aot) fail(path + ' is not an array of tables')
    const t = table(); t.hdr = true
    n.items.push(t)
    return { cur: t, path: keys }
  }
  if (n === undefined) {
    const t = table(); t.hdr = true
    parent.m.set(last, t)
    return { cur: t, path: keys }
  }
  if (n.t !== 'table') fail(path + ' is not a table')
  if (n.hdr) fail('table ' + path + ' is defined twice')
  n.hdr = true
  return { cur: n, path: keys }
}

function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = table()
  let cur = root
  let path = []
  lines.forEach((s, idx) => {
    try {
      const L = new Line(s)
      const c = L.peek()
      if (c === undefined) return
      if (c === '[') {
        const r = parseHeader(L, root)
        cur = r.cur; path = r.path
        return
      }
      const keys = parseDotted(L)
      if (L.peek() !== '=') fail('expected key = value')
      L.i++
      const v = parseValue(L, path.concat(keys))
      if (L.peek() !== undefined) fail('trailing text after a value')
      assign(cur, path, keys, v)
    } catch (e) {
      if (e instanceof ConfError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sortedKeys = (n) => [...n.m.keys()].sort(cmp)

function toJson(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sortedKeys(n)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => pad + JSON.stringify(k) + ': ' + toJson(n.m.get(k), ind + 1)).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((v) => pad + toJson(v, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  if (n.t === 'integer') return n.v.toString()
  return JSON.stringify(n.v)
}

function keysOut(n, path, out) {
  if (n.t === 'table') {
    for (const k of sortedKeys(n)) {
      const p = path === '' ? k : path + '.' + k
      const c = n.m.get(k)
      out.push(p + ' ' + c.t)
      keysOut(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = path + '[' + i + ']'
      out.push(p + ' ' + c.t)
      keysOut(c, p, out)
    })
  }
}

const args = process.argv.slice(2)
if (args.length !== 1 || (args[0] !== 'json' && args[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}
let doc
try {
  doc = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ConfError)) throw e
  process.stderr.write('error: ' + e.message + '\n')
  process.exit(2)
}
if (args[0] === 'json') {
  process.stdout.write(toJson(doc, 0) + '\n')
} else {
  const out = []
  keysOut(doc, '', out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
"}

