      if (n === undefined) fail('unterminated string')
      const map = { '"': '"', '\\': '\\', n: '\n', t: '\t', r: '\r', 0: '\0' }
      if (Object.hasOwn(map, n)) { out += map[n]; L.i += 2; continue }
      if (n === 'u') {
        const h = s.slice(L.i + 2, L.i + 6)
        if (!/^[0-9a-fA-F]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        L.i += 6
        continue
      }
      fail('invalid escape \\' + String.fromCodePoint(s.codePointAt(L.i + 1)))
    }
    out += c
    L.i++
  }
}

function parseName(L) {
  const c = L.s[L.i]
  if (c === '"' || c === "'") return parseString(L, c)
  const st = L.i
  while (isBare(L.s[L.i])) L.i++
